ProgressIndicator());if(s.data!.docs.isEmpty)return _empty(appText(c,km:'មិនទាន់មានប្រវត្តិឈ្នះ',en:'No wins yet'));return ListView(children:s.data!.docs.map((d){final x=d.data()as Map<String,dynamic>;return ListTile(leading:const Icon(Icons.emoji_events,color:Colors.amber),title:Text((x['product_name']??appText(c,km:'គ្មានឈ្មោះ',en:'Unnamed')).toString()),trailing:Text('${NumberFormat('#,###').format(x['current_price']??0)} ៛'));}).toList());});Widget _empty(String m)=>_InfoCard(children:[Padding(padding:const EdgeInsets.all(24),child:Center(child:Text(m)))]);}
