class _InfoCard extends StatelessWidget{final List<Widget>children;const _InfoCard({required this.children});@override Widget build(BuildContext c)=>Container(decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(15)),child:Column(children:children));}
class _ProfileSkeletonLoader extends StatelessWidget{const _ProfileSkeletonLoader();@override Widget build(BuildContext c)=>const Center(child:CircularProgressIndicator());}
class _ErrorStateWidget extends StatelessWidget{const _ErrorStateWidget();@override Widget build(BuildContext c)=>Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[const Icon(Icons.person_off,size:80),Text(appText(c,km:'មិនអាចរកឃើញអ្នកប្រើប្រាស់នេះបានទេ',en:'User not found')),ElevatedButton(onPressed:()=>Navigator.pop(c),child:Text(appText(c,km:'ត្រឡប់ក្រោយ',en:'Back')))]));}
class _ActivitySection extends StatelessWidget{final Map<String,dynamic>data;const _ActivitySection({required this.data});@override Widget build(BuildContext c){String f(dynamic t)=>t is Timestamp?DateFormat('dd/MM/yyyy HH:mm','km_KH').format(t.toDate()):appText(c,km:'មិនទាន់មានទិន្នន័យ',en:'No data yet');return _InfoCard(children:[ListTile(leading:const Icon(Icons.login_rounded,color:Colors.blue),title:Text(appText(c,km:'ចូលប្រើចុងក្រោយ',en:'Last login')),subtitle:Text(f(data['lastLogin']))),const Divider(height:1),ListTile(leading:const Icon(Icons.update_rounded,color:Colors.orange),title:Text(appText(c,km:'កែប្រែទិន្នន័យចុងក្រោយ',en:'Last updated')),subtitle:Text(f(data['lastUpdate'])))]);}}
